#!/usr/bin/env node

// js/scripts/prepare-desktop.mjs
//
// Stage the Electron desktop app (issue #37) under `dist/desktop/app/`
// so electron-builder packages only what the app needs at runtime:
//
//   - js/src/      — the local server, storage and the SPA (including
//                    the prebuilt app.min.js);
//   - js/electron/ — the Electron main process and preload script;
//   - package.json — generated by `desktopPackageJson()`: the root
//                    version, `main: js/electron/main.js`, and
//                    electron-updater as the only dependency;
//   - node_modules — `npm install --omit=dev` of that package.json.
//
// The root package.json cannot be packaged directly: its devDependencies
// (eslint, esbuild, React, playwright, …) and optional peers would end
// up in, or confuse, the installer, and electron-builder requires
// `electron` to be a devDependency, never a dependency.
//
// Usage:
//   node js/scripts/prepare-desktop.mjs [--out=dist/desktop/app] [--skip-install]
// then:
//   npx electron-builder --config desktop/electron-builder.config.cjs \
//     --projectDir dist/desktop/app --publish never

import { execFileSync } from 'node:child_process';
import { cp, mkdir, readFile, rm, writeFile } from 'node:fs/promises';
import { existsSync } from 'node:fs';
import { dirname, join, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';
import { validateDesktopUpdater } from './validate-desktop-updater.mjs';

const HERE = dirname(fileURLToPath(import.meta.url));
const ROOT = resolve(HERE, '..', '..');

export const DESKTOP_PRODUCT_NAME = 'Meta Sovereign';
export const DESKTOP_PACKAGE_NAME = 'meta-sovereign-desktop';
// electron-builder names the Linux .desktop entry after `executableName`;
// Electron uses `desktopName` as the Wayland app_id / X11 WM_CLASS, so
// the two must match for docks to group the running window with it.
export const DESKTOP_ENTRY_NAME = 'meta-sovereign.desktop';
export const DESKTOP_AUTHOR = Object.freeze({
  name: 'Link Foundation',
  email: 'link-foundation@users.noreply.github.com',
});

// Copied verbatim into the staged app. Everything the Electron main
// process imports lives under these two directories.
export const DESKTOP_SOURCE_DIRS = Object.freeze(['js/src', 'js/electron']);

// Built web assets the SPA needs at runtime.
export const DESKTOP_REQUIRED_FILES = Object.freeze([
  'js/electron/main.js',
  'js/electron/preload.cjs',
  'js/src/server/index.js',
  'js/src/web/index.html',
  'js/src/web/app.min.js',
]);

/**
 * The package.json electron-builder sees. Pure, so tests can check it
 * without touching the file system.
 */
export const desktopPackageJson = (rootPkg) => ({
  name: DESKTOP_PACKAGE_NAME,
  productName: DESKTOP_PRODUCT_NAME,
  desktopName: DESKTOP_ENTRY_NAME,
  version: rootPkg.version,
  description: rootPkg.description,
  license: rootPkg.license,
  author: { ...DESKTOP_AUTHOR },
  homepage: 'https://link-foundation.github.io/meta-sovereign/',
  repository: rootPkg.repository,
  type: 'module',
  main: 'js/electron/main.js',
  private: true,
  dependencies: {
    'electron-updater': rootPkg.peerDependencies['electron-updater'],
  },
  // Both methods return the same deep-comparison boolean with two arguments.
  // Scope the exact alias to updater 6; aliasing the whole lodash package
  // instead would return a truthy wrapper and accept changed update metadata.
  // Remove after electron-builder#10016 ships a compatible updater fix.
  overrides: {
    'electron-updater': {
      'lodash.isequal': 'npm:lodash.isequalwith@4.4.0',
    },
  },
});

const parseArgs = (argv) => {
  const args = { out: join(ROOT, 'dist', 'desktop', 'app'), install: true };
  for (const arg of argv) {
    if (arg.startsWith('--out=')) {
      args.out = resolve(arg.slice('--out='.length));
    } else if (arg === '--skip-install') {
      args.install = false;
    }
  }
  return args;
};

const npmInstall = (cwd) => {
  // `shell` lets Windows resolve npm.cmd; all arguments are constants.
  execFileSync(
    'npm',
    [
      'install',
      '--omit=dev',
      '--no-audit',
      '--no-fund',
      '--ignore-scripts',
      '--no-package-lock',
    ],
    { cwd, stdio: 'inherit', shell: process.platform === 'win32' }
  );
};

export const prepareDesktop = async ({
  root = ROOT,
  out = join(ROOT, 'dist', 'desktop', 'app'),
  install = true,
} = {}) => {
  for (const file of DESKTOP_REQUIRED_FILES) {
    if (!existsSync(join(root, file))) {
      throw new Error(
        `missing ${file}; run \`npm run build:web\` before preparing the desktop app`
      );
    }
  }
  const rootPkg = JSON.parse(
    await readFile(join(root, 'package.json'), 'utf8')
  );
  await rm(out, { recursive: true, force: true });
  await mkdir(out, { recursive: true });
  for (const dir of DESKTOP_SOURCE_DIRS) {
    await cp(join(root, dir), join(out, dir), { recursive: true });
  }
  for (const file of ['LICENSE', 'README.md']) {
    if (existsSync(join(root, file))) {
      await cp(join(root, file), join(out, file));
    }
  }
  const pkg = desktopPackageJson(rootPkg);
  await writeFile(
    join(out, 'package.json'),
    `${JSON.stringify(pkg, null, 2)}\n`
  );
  if (install) {
    npmInstall(out);
    await validateDesktopUpdater(out);
  }
  return { out, pkg };
};

const isMain = () => {
  const invokedAs = process.argv[1] && resolve(process.argv[1]);
  return invokedAs === fileURLToPath(import.meta.url);
};

if (isMain()) {
  const args = parseArgs(process.argv.slice(2));
  const { out, pkg } = await prepareDesktop(args);
  console.log(`Staged ${pkg.productName} ${pkg.version} desktop app in ${out}`);
}
